import math
for i in range(6):
    o = observe()
    h = o['hitch_deg']
    equilibrium = math.degrees(math.atan(2.5*math.sin(math.radians(h))/(3.6+1.3*math.cos(math.radians(h)))))
    steer = max(-20, min(20, equilibrium + 0.9*h))
    try:
        r = drive(steer, -0.25, 0.4)
    except LegOver:
        break
    if r['obs']['status'] in ('FINISHED', 'TIME_UP', 'DNF'):
        break

for i in range(12):
    o = observe()
    if o['status'] in ('FINISHED', 'TIME_UP', 'DNF'):
        break
    h = o['hitch_deg']
    b = o.get('route', {}).get('bearing_deg', 0)
    steer = max(-35, min(35, 2.0*h - 0.7*b))
    try:
        drive(steer, -0.5, 0.8)
    except LegOver:
        break
print(report())
